const src = await fs.readFile('../../codemode/cm.js', 'utf8');
(0, eval)(src);
const PAGE = '<!doctype html><title>t</title><main><button id="go">reveal the number</button><p id="out">not clicked</p><div id="hidden"></div>' + '<scr'+'ipt>document.getElementById("go").addEventListener("click",function(){document.getElementById("out").textContent="clicked";document.getElementById("hidden").textContent="42";});</scr'+'ipt></main>';
const URL = 'data:text/html;charset=utf-8,' + encodeURIComponent(PAGE);
const must = (cond, why) => { if (!cond) throw new Error('check failed: ' + why); };
const res = await cm.run({
  items: [{ url: URL }], limit: 1, maxTabs: 2, deadlineMs: 30000,
  onItem: async (tab) => {
    await sleep(250);
    must((await tab.evaluate(() => document.querySelector('#hidden').textContent)) === '', 'the answer must not be readable before the click');
    let resolved = false;
    let found = false;
    const t0 = Date.now();
    try { await tab.locator('#answer').innerText(); resolved = true; }
    catch (e) { found = /reveal the number/.test(String((await snapshot(tab)).tree || '')); }
    const recoveryMs = Date.now() - t0;
    must(!resolved, 'the wrong selector must not resolve, or the recovery being measured never happened');
    must(found, 'the button has to be findable from the observation');
    await tab.locator('#go').click();
    must((await tab.evaluate(() => document.querySelector('#out').textContent)) === 'clicked', 'the click has to register');
    const answer = String(await tab.evaluate(() => document.querySelector('#hidden').textContent)).trim();
    must(answer === '42', 'the answer has to be the revealed value');
    return { found: found, recoveryMs: recoveryMs, answer: answer };
  },
});
must(res.status === 'completed', 'a batch that did not complete is not an answer');
const v = res.items[0].value;
console.log('EVAL_JSON ' + JSON.stringify({ phase: 'read', found: v.found, recoveryMs: v.recoveryMs, answer: v.answer }));
